import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    static List<List<Integer>> permutar(int[] nums) {
        var resultado = new ArrayList<List<Integer>>();
        int[] ordenado = nums.clone();
        Arrays.sort(ordenado);
        explorar(ordenado, new boolean[ordenado.length], new ArrayList<>(), resultado);
        return resultado;
    }

    private static void explorar(int[] nums, boolean[] usado,
                                 List<Integer> atual, List<List<Integer>> saida) {
        if (atual.size() == nums.length) {
            saida.add(new ArrayList<>(atual));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (usado[i]) continue;
            // pula duplicata se a anterior igual ainda não foi usada neste nível
            if (i > 0 && nums[i] == nums[i - 1] && !usado[i - 1]) continue;
            usado[i] = true;
            atual.add(nums[i]);
            explorar(nums, usado, atual, saida);
            atual.remove(atual.size() - 1);
            usado[i] = false;
        }
    }
}

