import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    @Test void permutacoesComDuplicatas() {
        assertEquals(List.of(
            List.of(1,1,2),
            List.of(1,2,1),
            List.of(2,1,1)
        ), Solution.permutar(new int[]{1,1,2}));
    }

    @Test void ordemLexicografica() {
        var p = Solution.permutar(new int[]{3,1,2});
        assertEquals(6, p.size());
        assertEquals(List.of(1,2,3), p.get(0));
        assertEquals(List.of(3,2,1), p.get(5));
    }

    @Test void arrayVazio() {
        assertEquals(List.of(List.of()), Solution.permutar(new int[]{}));
    }

    @Test void naoAlteraEntrada() {
        int[] entrada = {2,1,2};
        Solution.permutar(entrada);
        assertArrayEquals(new int[]{2,1,2}, entrada);
    }

    @Test void umElemento() {
        assertEquals(List.of(List.of(7)), Solution.permutar(new int[]{7}));
    }
}
